    fn operations_are_exposed_for_inspection() {
        let doc = Document::from("hello");
        let tx = Transaction::insert(&doc, &Selection::point(0), "X");
        assert_eq!(
            tx.operations(),
            &[
                Operation::Retain(0),
                Operation::Insert("X".to_string()),
