        let doc = Document::from("hello");
        assert_eq!(
            move_selection(
                &doc,
                &Selection::point(0),
                Movement::Char,
                Direction::Forward
            ),
            Selection::point(1)
        );
        assert_eq!(
            move_selection(
                &doc,
                &Selection::point(4),
                Movement::Char,
                Direction::Forward
            ),
            Selection::point(5)
        );
        // 文書端では動かない
        assert_eq!(
            move_selection(
                &doc,
                &Selection::point(5),
                Movement::Char,
                Direction::Forward
            ),
            Selection::point(5)
        );
        assert_eq!(
            move_selection(
                &doc,
