            let children: Vec<Node> = s.children.into_iter().map(collapse).collect();
            match children.len() {
                1 => children.into_iter().next().expect("要素数1"),
                0 => unreachable!("空の Split は発生しない"),
                _ => Node::Split(Split {
                    direction: s.direction,
                    children,
                }),
            }
        }
        node => node,
    }
}

