//! モード: モーダル編集の状態。

/// モーダル編集のモード。
#[derive(Clone, Copy, Debug, Default, PartialEq, Eq)]
pub enum Mode {
    /// ナビゲーションと編集コマンド。
    #[default]
    Normal,
    /// テキスト入力。
    Insert,
    /// 移動で選択が伸びる（extend）モード。
    Select,
}
//! mina のテキスト編集コア: 端末非依存の文書・選択・トランザクション・移動・編集のモデル。
//!
//! コアは関数型である: 操作は状態を破壊的に変更するのではなく、新しい状態を
//! 返す（`docs/adr/0002-functional-core-selection.md` 参照）。
//! この層はターミナル・キーマップ・構文ハイライトについて何も知らない。

pub mod document;
pub mod edit;
pub mod movement;
pub mod search;
pub mod selection;
pub mod transaction;

pub use document::Document;
pub use edit::{
    delete_backward, delete_backward_transaction, delete_forward, delete_forward_transaction,
    delete_range, insert_text,
};
pub use movement::{Direction, Movement, extend_selection, move_selection};
pub use ropey::Rope;
pub use search::{CaseSensitivity, find_matches, find_next};
pub use selection::{Range, Selection};
pub use transaction::{Operation, Transaction};
//! mina のビュー層: UI 非依存のエディタ状態（imperative shell）。
//!
//! 関数型のコア（mina-core）は状態を持たず、「文書と選択を新しい状態に変換
//! する」ことだけをする。この層はその**現在の状態**を保持する: 開いている
//! 文書の集合、アクティブな View（どの文書をどの選択で表示しているか）、
//! モード、undo/redo の履歴。将来のターミナル UI（mina-term）はこの層に
//! 依存し、コマンドはここを経由してコアを呼ぶ。
//!
//! レイアウト: viewport（先頭行）と分割ツリーは実装済み。水平スクロール・
//! 折り返しはターミナル描画の段階で追加する。

pub mod editor;
pub mod history;
pub mod mode;
pub mod tree;

pub use editor::{DocumentId, Editor, View};
pub use history::History;
pub use mode::Mode;
pub use tree::{SplitDirection, Tree, ViewId};

