#[test]
fn temp_undo_group_survives_quit_in_insert_mode() {
    // Insert で入力 → Esc せずに切断（daemon は grouping=true のまま）
    let mut d = daemon();
    open(&mut d, "");
    apply(&mut d, Command::SetMode { mode: Mode::Insert });
    for ch in ["a", "b", "c"] {
        apply(&mut d, Command::Insert { text: ch.into() });
    }
    // クライアント切断を模擬: SetMode(Normal) は送られない。grouping は true のまま
    // 別のセッションが再接続して入力
    apply(&mut d, Command::SetMode { mode: Mode::Insert });
    for ch in ["d", "e"] {
        apply(&mut d, Command::Insert { text: ch.into() });
    }
    apply(&mut d, Command::SetMode { mode: Mode::Normal });
    assert_eq!(d.editor.current_document().text().to_string(), "abcde");
    let s = apply(&mut d, Command::Undo);
    // 期待: 最後のセッションの "de" だけ戻る → "abc"
    // 実際: グループが1つに統合され "" に戻る
    eprintln!("TEMP undo result text: {:?}", s.text);
}

#[test]
fn temp_undo_group_insert_to_select_leaks_open_group() {
    let mut d = daemon();
    open(&mut d, "");
    apply(&mut d, Command::SetMode { mode: Mode::Insert });
    apply(&mut d, Command::Insert { text: "a".into() });
    // Insert → Select は end_group なし
    apply(&mut d, Command::SetMode { mode: Mode::Select });
    apply(&mut d, Command::SetMode { mode: Mode::Normal });
    // Normal → Insert は begin_group（grouping は既に true）
    apply(&mut d, Command::SetMode { mode: Mode::Insert });
    apply(&mut d, Command::Insert { text: "b".into() });
    apply(&mut d, Command::SetMode { mode: Mode::Normal });
    let s = apply(&mut d, Command::Undo);
    eprintln!("TEMP undo2 result text: {:?} (expect \"\" if merged, \"a\" if separate)", s.text);
}

