#[test]
fn temp_crlf_line_is_erased() {
    // CRLF 行: 行内容 "a\r" を描画すると \r でカーソルが行頭に戻り、
    // \x1b[K が行全体を消す
    let state = state_with("a\r\nb\r\n", vec![Range { anchor: 0, head: 0 }], 0);
    let out = render_text(&state, &[], 40, 10);
    // 行1の描画: 位置付け → "a\r" → \x1b[K
    let row1 = out.split("\x1b[1;1H").nth(1).unwrap_or("");
    let before_erase = row1.split("\x1b[K").next().unwrap_or("");
    eprintln!("TEMP crlf row1 segment: {:?}", before_erase);
    assert!(
        before_erase.contains('a'),
        "a が出力されているはず: {:?}",
        before_erase
    );
    let row2 = out.split("\x1b[2;1H").nth(1).unwrap_or("");
    let before_erase2 = row2.split("\x1b[K").next().unwrap_or("");
    eprintln!("TEMP crlf row2 segment: {:?}", before_erase2);
    assert!(
        before_erase2.contains('b'),
        "b が出力されているはず: {:?}",
        before_erase2
    );
}

